import MuseumObjectEngine from './MuseumObjectEngine'
import LifestyleHouses from './LifestyleHouses'
import ReferenceGallery from './ReferenceGallery'
import { CoreSaved, CoreHouses, CorePassport, CoreGallery, CoreCollection, CoreObject, CoreFit, CoreDesigns, CoreWorld } from './CoreExperience'
import { useAuthStore } from '@/features/auth/store/auth.store'
import { createContext, useContext, useCallback, useEffect, useId, useState } from 'react'
import type { FormEvent, ReactNode } from 'react'
import { Link, NavLink, useLocation, useNavigate, useParams, useSearchParams } from 'react-router-dom'
import QRCode from 'qrcode'
